// src/app/api/auth/[...nextauth]/route.ts
import NextAuth, { NextAuthOptions } from "next-auth"
import CredentialsProvider from "next-auth/providers/credentials"
import { FirestoreAdapter } from "@next-auth/firebase-adapter" // <-- NAMA YANG BENAR
import { firestore } from "@/lib/firebase"
import { collection, query, where, getDocs } from "firebase/firestore"

// Definisikan tipe tambahan untuk session dan token
declare module "next-auth" {
  interface Session {
    user?: {
      role?: string | unknown;
    } & {
      name?: string | null;
      email?: string | null;
      image?: string | null;
    };
  }
  interface User {
    role?: string | unknown;
  }
}
declare module "next-auth/jwt" {
  interface JWT {
    role?: string | unknown;
  }
}


export const authOptions: NextAuthOptions = {
  providers: [
    CredentialsProvider({
      name: 'Credentials',
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" }
      },
      async authorize(credentials, req) {
        if (!credentials?.email || !credentials?.password) {
          return null
        }

        const q = query(collection(firestore, "users"), where("email", "==", credentials.email));
        const userDocs = await getDocs(q);

        if (userDocs.empty) {
          return null
        }

        const user = userDocs.docs[0].data();
        
        // Nanti di sini ganti dengan perbandingan hash password (bcrypt)
        if (user.password === credentials.password) {
          return {
            id: userDocs.docs[0].id,
            email: user.email,
            name: user.name,
            role: user.role,
          }
        }
        
        return null
      }
    })
  ],
  adapter: FirestoreAdapter(firestore as any), // <-- NAMA YANG BENAR
  session: {
    strategy: "jwt",
  },
  callbacks: {
    async jwt({ token, user }) {
      if (user) {
        token.role = user.role;
      }
      return token;
    },
    async session({ session, token }) {
      if (session?.user) {
        session.user.role = token.role;
      }
      return session;
    }
  },
  pages: {
    signIn: '/login',
  }
};

const handler = NextAuth(authOptions);

export { handler as GET, handler as POST };